-- Table: hrm_payroll_detail
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_payroll_detail (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    payroll_run_id      BIGINT NOT NULL REFERENCES hrm_payroll_run(id) ON DELETE CASCADE,
    line_number         INTEGER NOT NULL CHECK (line_number > 0),
    employee_id         BIGINT NOT NULL REFERENCES masterdata_employee(id),
    basic_salary        NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (basic_salary >= 0),
    allowances          NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (allowances >= 0),
    overtime_amount     NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (overtime_amount >= 0),
    gross_salary        NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (gross_salary >= 0),
    tax_amount          NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
    statutory_deduction NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (statutory_deduction >= 0),
    other_deductions    NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (other_deductions >= 0),
    net_salary          NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (net_salary >= 0),
    cost_center_id      BIGINT REFERENCES masterdata_cost_center(id),
    bank_account_id     BIGINT REFERENCES masterdata_bank_account(id),
    payslip_sent_at     TIMESTAMPTZ,
    notes               TEXT,
    UNIQUE (payroll_run_id, line_number),
    UNIQUE (payroll_run_id, employee_id)
);
